// SFTP get/put against server .215 for the booking-features build.
// Never prints the password. Asserts identity via connectionTarget/ipAddress.
// Usage: node scripts/_wt-io.mjs get <remotePath> <localPath>
//        node scripts/_wt-io.mjs put <localPath> <remotePath>
import { PrismaClient } from "@prisma/client";
import { Client } from "ssh2";
import { scryptSync, createDecipheriv } from "node:crypto";
import fs from "node:fs";

const EXPECT_IP = "51.79.226.215";
const SERVER_ID = "cmsecmdps0001hlp27ai6mr7c";

for (const line of fs.readFileSync("/opt/nxeon/.env", "utf8").split("\n")) {
  const m = line.match(/^([A-Z0-9_]+)=(.*)$/);
  if (m && !(m[1] in process.env)) process.env[m[1]] = m[2].replace(/^["']|["']$/g, "");
}
function derive() { return scryptSync(process.env.AUTH_SECRET, "nxeon-byok", 32); }
function decrypt(enc) {
  if (!enc) return null;
  const [iv, tag, data] = enc.split(":");
  if (!iv || !tag || !data) return null;
  const d = createDecipheriv("aes-256-gcm", derive(), Buffer.from(iv, "base64"));
  d.setAuthTag(Buffer.from(tag, "base64"));
  return Buffer.concat([d.update(Buffer.from(data, "base64")), d.final()]).toString("utf8");
}

const [mode, a, b] = process.argv.slice(2);
if (!["get", "put"].includes(mode) || !a || !b) { console.error("usage: get|put src dst"); process.exit(2); }

const db = new PrismaClient();
const s = await db.server.findUnique({ where: { id: SERVER_ID }, include: { dedicatedIp: true } });
await db.$disconnect();
if (!s) { console.error("server not found"); process.exit(1); }
const dedicated = !!s.dedicatedIp;
const host = dedicated ? s.dedicatedIp.address : (process.env.PUBLIC_IP || s.ipAddress || "");
const port = dedicated ? 22 : (s.sshPort || 22);
const password = decrypt(s.rootPasswordEnc) ?? s.rootPassword;
if (!password) { console.error("no root password"); process.exit(1); }
if (host !== EXPECT_IP && s.ipAddress !== EXPECT_IP && s.dedicatedIp?.address !== EXPECT_IP) {
  console.error(`REFUSING: host ${host} != ${EXPECT_IP}`); process.exit(3);
}
const connectHost = host === EXPECT_IP ? host : EXPECT_IP;

const conn = new Client();
const code = await new Promise((resolve) => {
  conn.on("ready", () => {
    conn.sftp((err, sftp) => {
      if (err) { console.error(err.message); conn.end(); return resolve(1); }
      if (mode === "get") {
        const ws = fs.createWriteStream(a === "-" ? "/dev/stdout" : b);
        const rs = sftp.createReadStream(a);
        rs.on("error", (e) => { console.error(e.message); conn.end(); resolve(1); });
        ws.on("close", () => { conn.end(); resolve(0); });
        rs.pipe(ws);
      } else {
        const rs = fs.createReadStream(a);
        const ws = sftp.createWriteStream(b);
        rs.on("error", (e) => { console.error(e.message); conn.end(); resolve(1); });
        ws.on("close", () => { conn.end(); resolve(0); });
        ws.on("error", (e) => { console.error(e.message); conn.end(); resolve(1); });
        rs.pipe(ws);
      }
    });
  });
  conn.on("error", (e) => { console.error("SSH ERROR: " + e.message); resolve(255); });
  conn.connect({ host: connectHost, port, username: "root", password, readyTimeout: 20000 });
});
process.exit(code);

